const e={model:"qwen3.8:latest",digest:"22130167c4c20e20c7b71454612966ca8e8171e9b3cc8ab6ce8aa6cbfec79643",promptVersion:3,date:"2026-08-30",status:{"fe.character.awareness.why":"reviewed","fe.character.control.why":"reviewed","fe.character.endurance.why":"reviewed","fe.character.precision.why":"reviewed","fe.character.speed.why":"reviewed","fe.energy.recovery.auxiliary":"reviewed","fe.energy.recovery.dominant":"reviewed","fe.energy.recovery.inferior":"reviewed","fe.energy.recovery.shadow":"reviewed","fe.energy.recovery.tertiary":"reviewed","fe.feeder.ne":"reviewed","fe.feeder.ni":"reviewed","fe.feeder.se":"reviewed","fe.feeder.si":"reviewed","fe.feeder.te":"reviewed","fe.fieldNotes.mirror":"reviewed","fe.fieldNotes.vignette.fake":"reviewed","fe.fieldNotes.vignette.grip":"reviewed","fe.fieldNotes.vignette.loop":"reviewed","fe.fieldNotes.vignette.mistakenForFi":"reviewed","fe.fieldNotes.vignette.read":"reviewed","fe.fieldNotes.vignette.roomThatBreaks":"reviewed","fe.fieldNotes.vignette.showtime":"reviewed","fe.hero.heading":"reviewed","fe.hero.subtitle":"reviewed","fe.hero.tag":"reviewed","fe.lab.btn.celebrate.label":"reviewed","fe.lab.btn.celebrate.sub":"reviewed","fe.lab.btn.covert.label":"reviewed","fe.lab.btn.covert.sub":"reviewed","fe.lab.btn.deadlock.label":"reviewed","fe.lab.btn.deadlock.sub":"reviewed","fe.lab.btn.isolate.label":"reviewed","fe.lab.btn.isolate.sub":"reviewed","fe.lab.btn.reconcile.label":"reviewed","fe.lab.btn.reconcile.sub":"reviewed","fe.lab.btn.sync.label":"reviewed","fe.lab.btn.sync.sub":"reviewed","fe.lab.deck.dissonance":"reviewed","fe.lab.deck.harmony":"reviewed","fe.lab.gate.closed":"reviewed","fe.lab.gate.open":"reviewed","fe.lab.meter.pleasure":"reviewed","fe.lab.meter.stress":"reviewed","fe.lab.narration.celebrate":"reviewed","fe.lab.narration.celebrate2":"reviewed","fe.lab.narration.covert":"reviewed","fe.lab.narration.covertHintCoarse":"reviewed","fe.lab.narration.covertHintHover":"reviewed","fe.lab.narration.deadlock":"reviewed","fe.lab.narration.gate":"reviewed","fe.lab.narration.hover":"reviewed","fe.lab.narration.intro":"reviewed","fe.lab.narration.isolate":"reviewed","fe.lab.narration.isolate2":"reviewed","fe.lab.narration.reconcile":"reviewed","fe.lab.narration.reconcile2":"reviewed","fe.lab.narration.sync":"reviewed","fe.lab.state.ambient":"reviewed","fe.lab.state.attuned":"reviewed","fe.lab.state.concord":"reviewed","fe.lab.state.conducting":"reviewed","fe.lab.state.dissonant":"reviewed","fe.lab.state.severed":"reviewed","fe.lab.state.split":"reviewed","fe.lab.state.unreadable":"reviewed","fe.lab.telemetry.actual":"reviewed","fe.lab.telemetry.believed":"reviewed","fe.lab.telemetry.cogState":"reviewed","fe.lab.telemetry.cost":"reviewed","fe.lab.telemetry.crossHead":"reviewed","fe.lab.telemetry.diff":"reviewed","fe.lab.telemetry.sibPleasure":"reviewed","fe.lab.telemetry.sibStress":"reviewed","fe.lab.telemetry.twinHead":"reviewed","fe.lab.telemetry.visitFi":"reviewed","fe.meta.title":"reviewed","fe.slot.auxiliary":"reviewed","fe.slot.critical":"reviewed","fe.slot.demon":"reviewed","fe.slot.dominant":"reviewed","fe.slot.inferior":"reviewed","fe.slot.opposing":"reviewed","fe.slot.tertiary":"reviewed","fe.slot.trickster":"reviewed","fe.zoneA.canvasAria":"reviewed","fe.zoneB.ageNote":"reviewed","fe.zoneB.heading":"reviewed","fe.zoneB.lede":"reviewed","fe.zoneB.railAria":"reviewed","fe.zoneB.stageAria":"reviewed","fe.zoneC.heading":"reviewed","fe.zoneC.lede":"reviewed","fe.zoneC.unstableDefault":"reviewed","fe.zoneD.canvasAria":"reviewed","fe.zoneD.heading":"reviewed","fe.zoneD.kicker":"reviewed","fe.zoneD.lede":"reviewed","fe.zoneD.legendHtml":"reviewed","fe.zoneE.lede":"reviewed"}},n={_meta:e,"fe.character.awareness.why":"nach außen gerichtet: Was der Raum fühlt, ist schärfer als das, was Fe selbst tut","fe.character.control.why":"handelt gezielt, in Richtung eines Feldes, das es auswählt","fe.character.endurance.why":"Räume sind ihr Element — das Feld, das sie aufrechterhält, trägt sie zugleich.","fe.character.precision.why":"liest einen Raum auf feine Toleranzen; Maskieren ist das Einzige, was die Lese übertrumpft","fe.character.speed.why":"das Lesen und die Reaktion sind ein einziger Vorgang","fe.energy.recovery.auxiliary":"Schnell, sobald die Menschen, für die es da war, sich eingerichtet haben.","fe.energy.recovery.dominant":"Lädt in Gesellschaft auf — die einzige Funktion, deren Erholung nicht einsam verläuft.","fe.energy.recovery.inferior":"Das soziale Katergefühl: ~30 min globales Abdunkeln, und es braucht keine Übersetzung.","fe.energy.recovery.shadow":"Unvollständig — was hier gesagt wird, kostet morgen noch etwas.","fe.energy.recovery.tertiary":"Langsamer: Charme ist in Stößen erschwinglich, nicht über einen ganzen Abend.","fe.feeder.ne":{figure:"Phantom-Träger treten in den Ring ein; der Aufwand-Messer zahlt trotzdem für sie.",mechanism:"Der ESFJ-Loop, bei dem Si herausgeschnitten ist: Ne — extravertierte Intuition — liefert Personen, die nicht im Raum sind, und sie treffen mit echtem Gewicht ein. Was sie denken könnten, wie dies ankommen könnte — der volle Preis wird gezahlt, um mit einem Publikum in Harmonie zu sein, das der Loop erzeugt hat. Die Funktion, die es brechen würde, ist Si's Aufzeichnung davon, wie diese Personen sich tatsächlich verhalten, und genau diese wird nicht konsultiert.",pair:"ESFJ Fe–Ne-Loop",provenance:"community",warn:"Loop-Kopplung: dominant und tertiär, beide extravertiert — die Umlaufbahn verläuft vollständig außerhalb des Selbst."},"fe.feeder.ni":{figure:"Prognosegeister reiten auf jedem Träger, und das Verhalten zielt auf den Geist.",mechanism:"Ni — introvertierte Intuition — übergibt Fe eine Trajektorie statt eines Schnappschusses: nicht die Stimmung, in der jemand ist, sondern die, auf die er zusteuert. Weniger Menschen, viel weiter voraus gelesen. Ungewöhnlich, wenn es trifft; still anmaßend, wenn es nicht trifft — diese Kopplung beantwortet Fragen, die noch niemand gestellt hat, und gelegentlich die falschen.",pair:"INFJ · ENFJ-Kopplung",provenance:"myers"},"fe.feeder.se":{figure:"Beobachte, wie das Tor schwingt — Charisma ohne Richtung.",mechanism:"Der ENFJ-Loop, mit Ni herausgeschnitten: Se — extravertiertes Empfinden — steuert die Pflege durch das, was in diesem Moment am lautesten ist. Die Zustimmung wirkt von Moment zu Moment hoch und akkumuliert nie, weil das Ziel ständig in Bewegung ist. Beide Funktionen richten sich nach außen, sodass nichts innerhalb des Loops sie überprüfen kann.",pair:"ENFJ Fe–Se-Loop",provenance:"community",warn:"Loop-Kopplung: dominant und tertiär, beide extravertiert — die Umlaufbahn verläuft vollständig außerhalb des Selbst."},"fe.feeder.si":{figure:"Ein Band aus vergangenen Zuständen zieht sich hinter jedem Träger, und der Ring neigt sich zu den Bändern.",mechanism:"Si — introvertierte Sensorik — übergibt Fe ein gespeichertes Protokoll jeder Person: wer sie bei jeder früheren Zusammenkunft war. Das Ziel wird zum Präzedenzfall statt zum lebendigen Durchschnitt — Gastfreundschaft, Tradition, der bewährte Abend, getragen von jemandem, der sich daran erinnert, wie es abläuft. Der Fehlschlag: Ein Raum, der zu einer Version seiner selbst gesteuert wird, die er bereits überwachsen hat.",pair:"ISFJ · ESFJ-Kopplung",provenance:"myers"},"fe.feeder.te":{figure:"Die Träger erstarrten mitten in der Phase, während der Ring den Raum von gestern weiter dirigiert.",mechanism:"Te — extravertiertes Denken — übergibt Fe Urteile über Ergebnisse statt Wahrnehmungen von Personen, sodass das Modell jeder Person aufhört, sich zu aktualisieren, und die Pflege im letzten bekannten Zustand läuft. Der Raum bewegt sich; das Modell nicht; und keine wahrnehmende Funktion ist im Loop, um dies zu sagen. Echte Stacks wechseln aus genau diesem Grund zwischen Beurteilen und Wahrnehmen ab.",pair:"Beurteilung speist Beurteilung",provenance:"myers",warn:"Instabile Kopplung: Beurteilen speist Beurteilen, wobei für beide nichts wahrnimmt."},"fe.fieldNotes.mirror":{figure:"Auf den Glyphen, eine Sektion weiter oben: Der Umfang von Fi wird aus seinem Zentrum berechnet und brennt weiterhin allein; das Zentrum von Fe wird aus seinem Umfang berechnet, und man kann zusehen, wie es erlischt.",mechanismHtml:"Gleiches Element, entgegengesetzte Haltung – und der gesamte Unterschied liegt darin, wo die Messung erfolgt. <strong>Fi misst im Zentrum:</strong> ein fester innerer Ton, gegen den jeder Eingang geprüft wird. <strong>Fe misst am Perimeter:</strong> Der Maßstab wird aus den Anwesenden berechnet und bewegt sich mit ihnen. Deshalb scheitern sie in entgegengesetzten Richtungen: Isoliert man Fi, überlebt der Maßstab; isoliert man Fe, bleibt nichts übrig, woran gemessen werden könnte.",provenance:"jung"},"fe.fieldNotes.vignette.fake":{figure:"Es als falsch zu bezeichnen, heißt, einen Leuchtturm für unaufrichtig zu halten, weil er auf Schiffe scheint, die er nicht kennt.",kind:"die Anklage",mechanism:"Die Last trifft Fe mehr als jede andere Funktion und kehrt die Mechanik um. Die Wärme gegenüber jemandem, den Fe privat für schwierig hält, ist kein gefälschtes Gefühl; es ist Infrastruktur – die Raumtemperatur ist etwas, das diese Funktion aufrechterhält, so wie andere Menschen Brücken instand halten, und die Instandhaltung stoppt nicht wegen des persönlichen Wetters. Das Lächeln ist tragend.",provenance:"community",title:"Du verstellst dich nur"},"fe.fieldNotes.vignette.grip":{figure:"Eine kleine Kammer, plötzlich unter vollem Druck.",kind:"der Grip",mechanism:"Ein INTP, der seine Reserven erschöpft hat, hört auf zu analysieren und wird von inferior Fe überflutet: ein abruptes, rohes, schlecht kalibriertes Bedürfnis zu wissen, dass man hier willkommen ist, von jemandem, der die ganze Woche erklärt hat, dass soziale Konventionen willkürlich sind. Keine Persönlichkeitsänderung — ein Sitz mit niedriger Kapazität, der eine dominant große Flut aufnimmt.",provenance:"quenk",title:"Der Grip"},"fe.fieldNotes.vignette.loop":{figure:"Phantom-Träger, echte Rechnungen.",kind:"der Loop",mechanism:"Ein ESFJ unter Stress koppelt dominante Fe mit tertiärer Ne: Neigung zu Menschen, die nicht im Raum sind. Was sie vielleicht denken, was diese Nachricht vielleicht bedeutet hat, wie sie ankommen wird. Volle Anstrengung, kein Kontakt. Die Funktion, die es brechen würde – Si's tatsächliche Aufzeichnung, wie diese Menschen sich tatsächlich verhalten – ist genau die, die der Loop nicht mehr konsultiert.",provenance:"community",title:"Der Loop"},"fe.fieldNotes.vignette.mistakenForFi":{figure:"Die eine lenkt das Wetter; die andere bewahrt den Kompass darin.",kind:"die Fehldeutung",mechanism:"Beide werden als „die Warme“ gelesen, sodass die Haltungen zusammenbrechen. Das Erkennungsmerkmal ist, welches Signal sie zuerst bewegt. Fe registriert das Unbehagen des Raums vor dem eigenen – es kann persönlich wütend sein und dennoch die Verwirrung des neuen Mitarbeiters mitten im Satz bemerken. Fi registriert die eigene Linie vor der des Raums – es kann in einer angespannten Besprechung ruhig sitzen, bis ein Wert berührt wird, und sich dann allein gegen das gesamte Feld bewegen.",provenance:"community",title:"Mit Fi verwechselt"},"fe.fieldNotes.vignette.read":{figure:"Elf Sekunden Ringarbeit, ohne sichtbare Anstrengung.",kind:"Feldsichtung",mechanism:"Ein ENFJ betritt einen Raum und organisiert ihn in elf Sekunden neu — gibt einer Person den Sitz neben der, die sie herauslocken wird, richtet eine Frage an diejenige, die still war, löst eine Spannung, die noch niemand registriert hat. Später gefragt, was sie getan habe, kann sie es selten rekonstruieren: Lesen und Reaktion waren ein einziger Vorgang, und keiner von beiden durchlief die Sprache.",provenance:"community",title:"Das Lesen"},"fe.fieldNotes.vignette.roomThatBreaks":{figure:"Das Instrument misst den Zusammenhalt; es kann nicht messen, ob dieser Zusammenhalt es verdient, aufrechterhalten zu werden.",kind:"das falsche Instrument",mechanism:"Manche Felder sollten nicht harmonisiert werden: das Meeting, in dem ein schlechter Plan laut sterben muss, der Konsens, der jemanden still ausschließt, der Frieden, der nur die Abwesenheit einer Konfrontation ist, die jemand schuldet. Hier arbeitet der Reflex von Fe — die Lücke schließen, die Übereinstimmung wiederherstellen — gegen die eigentliche Reparatur und glättet einen Riss, der chirurgische Arbeit leistete. Manche Räume brauchen ein Zerlegen ihrer Kohärenz bevor jene etwas wert ist.",provenance:"currents",title:"Der Raum, der brechen muss"},"fe.fieldNotes.vignette.showtime":{figure:"Der Ring leuchtet für den Auftritt auf, dann geht er nach Hause.",kind:"als tertiär",mechanism:"Tertiäres Fe bei ESTP oder ENTP: Das Raumlesen wird in Stößen eingesetzt, als Werkzeug. Die Bar wird wärmer, der Kunde entspannt sich, der Störer wird in den Auftritt eingebunden – echte Fähigkeit, ehrlich genossen, und auf dem Parkplatz ohne zweiten Gedanken abgeschaltet. Das Feld war real, solange es aufrechterhalten wurde; was dieser Fe auf diesem Sitz nicht tut, ist, zu bleiben, um das Feld zu pflegen – der Unterschied zwischen dem Spielen mit den Neffen auf dem Familienausflug und der täglichen Erziehungsarbeit des Elternteils.",provenance:"grant",title:"Der Showtime-Schalter"},"fe.hero.heading":"Resonanzfeld von {fn}","fe.hero.subtitle":"Ein Ring aus anderen Menschen, die außerhalb der Kammer stehen und durch ein Gitter verbunden sind, das Fe zwischen ihnen konstruiert. Der Kern hat keine eigene Farbe — er ist der Durchschnitt aller, die sich gerade im Raum befinden.","fe.hero.tag":"extravertierte Gefühle","fe.lab.btn.celebrate.label":"Der Raum hebt sich","fe.lab.btn.celebrate.sub":"kollektive Feier, alle im Takt","fe.lab.btn.covert.label":"Der kalte Strom","fe.lab.btn.covert.sub":"verdeckte Feindseligkeit hinter einer sauberen Fassade","fe.lab.btn.deadlock.label":"Der Deadlock","fe.lab.btn.deadlock.sub":"zwei Cluster, antiphase verriegelt","fe.lab.btn.isolate.label":"Abtrennen","fe.lab.btn.isolate.sub":"Der Ring wird dunkel; Fe findet seine Farbe","fe.lab.btn.reconcile.label":"Abgleich","fe.lab.btn.reconcile.sub":"Getrenntes Feld verbinden — das teure","fe.lab.btn.sync.label":"Stille Synchronisation","fe.lab.btn.sync.sub":"Eine Person ändert sich; Fe passt sich an, ohne Kosten","fe.lab.deck.dissonance":"Dissonanz · Überlastung & Störung","fe.lab.deck.harmony":"Harmonie · hohe Kohärenz","fe.lab.gate.closed":"benötigt ein geteiltes Feld","fe.lab.gate.open":"Das Feld ist gespalten — brücke es","fe.lab.meter.pleasure":"Resonanz Genuss","fe.lab.meter.stress":"Stress","fe.lab.narration.celebrate":{figure:"Zwölf Oszillatoren synchronisieren sich, und die Interferenz in der Kammer wird vollständig konstruktiv — jeder Wellenberg trifft auf jeden anderen Wellenberg.",mechanism:"Alle sind auf derselben Frequenz und das Halten des Raums kostet fast nichts. Dies ist der Zustand, den Fe zu erzeugen existiert.",provenance:"currents"},"fe.lab.narration.celebrate2":{figure:"Beobachte, wie der Differenzierungsanzeige sinkt, während die Farbtöne zu einem einzigen Ton verschmelzen.",mechanism:"Vollständige Übereinstimmung ist vollständige Gleichheit: Ein Raum, der so synchronisiert ist, kann seine Mitglieder nicht mehr voneinander unterscheiden, und die erste Person, die einen anderen Ton anschlägt, wird als Angriff erlebt. Der charakteristische Fehlschlag von Fe tritt im exakten Moment seines größten Erfolgs auf.",provenance:"currents"},"fe.lab.narration.covert":{figure:"Die Vertrauenslücke ist das einzige bewegliche Instrument; darunter schlägt ein schwaches gegenläufiges Muster gegen das angezeigte Feld.",mechanism:"Die Zustimmung liest sich hoch, und der Stress steigt trotzdem. Sichtbar ist nichts Falsches — die Oberfläche ist sauber, alle melden sich gut — und doch registriert sich etwas. Dies ist die charakteristischste Fe-Erfahrung überhaupt und die schwerste zu verteidigen: ein reales Signal, das erkannt wird, bevor irgendein Beweis dafür existiert.",provenance:"currents"},"fe.lab.narration.covertHintCoarse":"Drücke und halte jeden Träger: Ob du das maskierte Paar findest, hängt davon ab, wo sich Fe im Stack befindet.","fe.lab.narration.covertHintHover":"Fahre mit der Maus über die Träger: Ob du das maskierte Paar findest, hängt davon ab, wo sich Fe im Stack befindet.","fe.lab.narration.deadlock":{figure:"Der leitende Begriff läuft nahe am Maximum; der Kern nimmt den Mittelwert zweier Gegensätze an und wird grau.",mechanism:"Zwei Fraktionen, in Opposition verhaftet, und Fe kann die Arbeit nicht ablehnen – der Aufwand ist nicht freiwillig und vollbringt nichts, solange der Spalt anhält. In zwei Hälften zerrissen zu werden durch einen Konflikt, an dem man nicht beteiligt ist, ist genau dieser Zustand. Hier löst sich nichts von selbst.",provenance:"currents"},"fe.lab.narration.gate":"Versöhnung braucht etwas, das versöhnt werden kann. Spalte zuerst das Feld — löse einen Stillstand aus oder lass einen kalten Strom zu einem gerinnen — und diese Steuerung wird freigeschaltet.","fe.lab.narration.hover":"Du lässt den Ring auf dich wirken. Jeder Träger meldet, was Fe über ihn aussagen kann: seine Amplitude, ob er in Phase ist und – wenn der Abgleich von Fe an dieser Stack-Position genau genug ist –, ob das, was er anzeigt, dem entspricht, was er tut.","fe.lab.narration.intro":"Der Ring läuft unbeaufsichtigt: sieben unabhängige Oszillatoren, die miteinander gekoppelt sind und von allem, was Fe übrig hat, angestoßen werden, treiben auf eine Übereinstimmung zu, die nie ganz abgeschlossen wird. Erzeuge ein Ereignis und beobachte, wie das Feld antwortet. Die beiden Zeilen sind keine Dekoration – alles oberhalb der Trennlinie macht den Raum kohärenter, und alles darunter nimmt etwas weg.","fe.lab.narration.isolate":{figure:"Die Träger werden dunkel, und der Kern folgt ihnen.",mechanism:"Dies ist die strukturelle Tatsache, auf die die gesamte Seite hinausläuft: Das Selbstverständnis von Fe wird aus den Menschen in der Nähe berechnet, und ohne diese gibt es keinen Durchschnitt. Fi allein kennt immer noch seinen eigenen Ton. Fe allein hat nichts, was es sein könnte.",provenance:"currents"},"fe.lab.narration.isolate2":{figure:"Die schwachen gestrichelten Träger sind keine Menschen; der Aufwandmesser kann keinen Unterschied feststellen.",mechanism:"Und die Arbeit hört nicht auf, wenn der Raum leer ist: Ein Publikum wird erfunden, damit es etwas gibt, mit dem harmonisiert werden kann. Volle Kosten, kein Kontakt — Grübeln, genau so gezeichnet, wie es funktioniert.",provenance:"currents"},"fe.lab.narration.reconcile":{figure:"Die Kopplung zwischen den beiden Clustern steigt von abstoßend hin zu positiv.",mechanism:"Maximale Anstrengung, steigender Stress und lange Zeit keine Verbesserung. Das ist die Arbeit: Alles aufzubieten gegen ein Feld, das sich noch nicht bewegt hat — ein Raum, der in Echtzeit aus einer Position herausverhandelt wird.",provenance:"currents"},"fe.lab.narration.reconcile2":{figure:"Die Null schließt sich, und eine Wellenfront durchquert beide Hälften gleichzeitig.",mechanism:"Jetzt lies die Kosten: rund vier Einheiten, gegenüber weniger als einer halben Einheit für die frühere Synchronisation. Der beste Moment von Fe ist um eine Größenordnung teurer – der Grund, warum Fe-Dominanten an Räumen ausbrennen, die sich nicht auflösen. Nicht, weil sie zu viel caren; sondern weil dies der tatsächliche Preis für das ist, was sie gut können.",provenance:"currents"},"fe.lab.narration.sync":{figure:"Eine einzelne Faser verbindet einen Träger mit dem Kern — die einzige Eins-zu-Eins-Verbindung in diesem Labor — und der Aufwandmesser bleibt flach.",mechanism:"Nichts wurde gesagt und nichts wurde aufgewendet. Die Stimmung einer Person verschob sich um ein paar Grad und die Reaktion geschah, bevor jemand sie hätte benennen können. Das Günstigste, was Fe tut, ist das, was niemand sehen kann, wie es es tut — was auch der Grund ist, warum es selten Anerkennung erhält.",provenance:"currents"},"fe.lab.state.ambient":"Offenes Feld","fe.lab.state.attuned":"Aufeinander Eingestellt","fe.lab.state.concord":"Konsens","fe.lab.state.conducting":"Dirigieren","fe.lab.state.dissonant":"Dissonanz","fe.lab.state.severed":"Getrenntes Feld","fe.lab.state.split":"Feld aufteilen","fe.lab.state.unreadable":"Ungelesener Strom","fe.lab.telemetry.actual":"Istwert","fe.lab.telemetry.believed":"Angenommen","fe.lab.telemetry.cogState":"Kognitiver Zustand","fe.lab.telemetry.cost":"Kosten dieses Ereignisses","fe.lab.telemetry.crossHead":"gleiche Ereignisse, erreichen Fi","fe.lab.telemetry.diff":"Differenzierung","fe.lab.telemetry.sibPleasure":"Fi-Freude","fe.lab.telemetry.sibStress":"Fi-Stress","fe.lab.telemetry.twinHead":"der Raum · geglaubt vs. tatsächlich","fe.lab.telemetry.visitFi":"Fi besuchen →","fe.meta.title":"Fe — Extravertierte Gefühle · CURRENTS","fe.slot.auxiliary":{example:"Ein INFJ richtet einmal im Monat ein Dinner für fünf Personen aus, und es ist makellos.",figure:"Ein kleinerer Ring, weniger Träger, saubereres Schloss.",mechanism:"Auf dem zweiten Sitz wird der Raum weiterhin genau gelesen, aber die Fürsorge ist selektiv und geplant: Pflege wird bewusst den Menschen zuteil, die die dominante Wahrnehmungsfunktion als bedeutsam entschieden hat, statt über jede Versammlung verteilt. Warm in einem engeren Band und deutlich schwerer zu erschöpfen.",provenance:"myers"},"fe.slot.critical":{example:"Ein ENFP befiehlt einem Freund beim Abendessen „des Tisches willen“ zu schweigen – den Tisch hat niemand gefragt.",figure:"Ein harter Stroboskopblitz über dem Ring, gerichtet auf einen Träger.",mechanism:"Auf dem sechsten Sitz wird das Erfassen der Raumstimmung zu Urteilen über die Wirkung anderer auf den Raum — du fällst allen zur Last, niemand will das hören — mit voller Selbstsicherheit, selten geprüft und auf den Nächsten gerichtet. Die Person, die es ausspricht, pflegt in diesem Moment nichts.",provenance:"beebe"},"fe.slot.demon":{example:"Ein Treffen wird einberufen, um „jeden zu hören“, dessen Sitzordnung, Reihenfolge und Rahmung darauf abzielen, einen Stuhl zu isolieren.",figure:"Der Ring wird absichtlich auseinandergetrieben, während die Anzeige weiterhin grün zeigt.",mechanism:"Der achte Sitz ist der seltenste und schärfste. Wenn er aktiv wird, wird Gruppengefühl zur Waffe: Ein Ton wird erzeugt, um jemanden darin zu isolieren, während der Handelnde weiterhin behauptet, dies diene dem Interesse aller. Es ist der am wenigsten geübte Sitz im Stack und unverkennbar, wenn er auftritt.",provenance:"beebe"},"fe.slot.dominant":{example:"Der Gastgeber gibt zwei Fremden einen Sitz nebeneinander und beide gehen mit dem Gefühl, der Abend sei einfach gut verlaufen.",figure:"CURRENTS zeichnet dies als einen Ring von Trägern in nahezu perfekter Übereinstimmung – beide Zeiger, der wahrgenommene und der tatsächliche, liegen exakt übereinander.",mechanism:"Im ersten Sitz ist der Zustand des Raums das primäre Datum, das kontinuierlich und mühelos gelesen wird — wer verstummt ist, wer übergangen wird, wo die Spannung sitzt. Harmonie ist keine Präferenz, sondern eine tragende Struktur: etwas, das die Person trägt, meist ungefragt und meist unbemerkt, bis sie aufhört.",provenance:"myers"},"fe.slot.inferior":{example:"Ein INTP, der die ganze Woche über die Beliebigkeit von Smalltalk referiert hat, fragt um 1 Uhr nachts, ob jemand bemerken würde, wenn sie nicht mehr kämen.",figure:"Ein schwacher Ring, bei niedriger Auflösung gelesen, der alles auf einmal überflutet.",mechanism:"Im vierten Sitz kostet Zugehörigkeit am meisten und es wird ihr am wenigsten vertraut. Soziale Konventionen lesen sich über lange Strecken als willkürliches Rauschen; bei echter Erschöpfung übernimmt ein abruptes, schlecht kalibriertes Bedürfnis zu wissen, dass sie hier erwünscht sind — Quenk's Grip — und trifft entweder viel zu hart oder gar nicht, was sie am meisten überrascht.",provenance:"quenk"},"fe.slot.opposing":{example:"Eine ISFP führt am Teambuilding-Tag jedes Ritual perfekt aus, einen Grad zu genau, und alle spüren es.",figure:"Unterhalb der Wasserlinie spielt der Ring das Muster des Feldes invertiert zurück.",mechanism:"Der fünfte Sitz öffnet den Schatten — die vier Positionen, die eine Person selten ausführt und meist ohne es zu bemerken. Hier läuft das Gruppeneinstimmen entgegengesetzt: Wenn ein innerer Wert unter Druck gerät, stimmt die Person den Ton des Raums mit beunruhigender Präzision ab, gerade um ihn abzulehnen — eine Harmonie, die echt genug ist, um erkannt zu werden, und die gezielt vorenthalten wird.",provenance:"beebe"},"fe.slot.tertiary":{example:"Ein ESTP nimmt den Störenfried in die Show auf, gewinnt das Publikum und vergisst die Namen aller am Parkplatz.",figure:"Der Ring leuchtet in Stößen auf und wird zwischen ihnen dunkel.",mechanism:"Im dritten Sitz ist Wärme ein Instrument: wirklich gefühlt, gezielt eingesetzt und zurückgezogen, wenn der Moment gewonnen ist. Das Situationsverständnis reicht für die nächsten zwanzig Minuten und wird selten danach geprüft – was zeigt, dass es der dritte und nicht der erste Sitz ist.",provenance:"grant"},"fe.slot.trickster":{example:"Ein INTJ verlässt die Party früh, in der Gewissheit, man habe sich über ihn lustig gemacht, wegen einer Geschichte, die zu seiner Ehre erzählt wurde.",figure:"Beobachte die Nadeln: Was dieser Sitz über den Raum glaubt und was wahr ist, haben sich sichtbar voneinander entfernt.",mechanism:"Im siebten Sitz liefert die soziale Lektüre selbstbewusste Fehler: Wärme wird für Spott gehalten, ein Witz für einen Angriff, ein Verbündeter für eine Bedrohung – und das Fehlurteil wird sofort umgesetzt, ohne Überprüfung. Die Blindheit ist real, nicht taktisch.",provenance:"beebe"},"fe.zoneA.canvasAria":"Interaktive visuelle Darstellung von extravertiertem Gefühl als Resonanzfeld: ein Ring unabhängiger Oszillatoren außerhalb einer sechseckigen Kammer, die über ein Gitter miteinander gekoppelt sind, wobei leitende Impulse durch eine Lücke im Rand den Kern verlassen. Das Interferenzmuster innerhalb der Kammer wird ausschließlich von den Trägern außerhalb erzeugt, und der Kern nimmt seine Farbe aus deren Durchschnitt an. Zeigen Sie auf einen Träger oder drücken Sie ihn an, um zu hören, was Fe über sie verraten kann","fe.zoneB.ageNote":"Mit dem Alter gewinnen die tieferen Stack-Positionen an Genauigkeit und Tastverhältnis – und der Ring selbst wird größer, liest mehr von sich auf einmal und stabilisiert sich.","fe.zoneB.heading":"Die acht Gesichter von Fe","fe.zoneB.lede":"Klicke auf eine Position, um zu sehen, wie der Raum den Besitzer wechselt – von der mühelosen Lesart der dominanten Funktion bis zur herbeigeführten Harmonie des Dämons. Beobachte die beiden Zeiger auf dem Glyphen: was Fe über den Raum glaubt und was tatsächlich wahr ist. Bei Dominant liegen sie übereinander; bis zum Trickster haben sie sich sichtbar voneinander entfernt, und das Fehlurteil wird bereits ausgeführt. Ziehe den Reiferegler, um zu sehen, wie der Ring mit dem Alter wächst und sich stabilisiert.","fe.zoneB.railAria":"Stack-Positionen für Fe","fe.zoneB.stageAria":"Glyph-Bühne, die die gewählte Stack-Position zeigt, mit einer Abgleichs-Anzeige zwischen vermuteter und tatsächlicher Übereinstimmung","fe.zoneC.heading":"Was speist Fe?","fe.zoneC.lede":"Extravertierte Beurteilung wird von introvertierter Wahrnehmung gespeist – die echten Partner von Fe sind Ni und Si, die inneren Wahrnehmungen, die ihm sagen, woraus der Raum besteht. Klicke auf einen Zubringer und beobachte, wozu Fe anfängt zu dirigieren.","fe.zoneC.unstableDefault":"Instabile Kopplung: Beurteilen speist Beurteilen, ohne dass für eines der beiden etwas wahrgenommen wird.","fe.zoneD.canvasAria":"Das Fe-Resonanzlabor: ein Ring gekoppelter Träger um eine offene hexagonale Kammer, in dem Harmonieereignisse das Feld in konstruktive Interferenz verriegeln und Dissonanzereignisse es maskieren, spalten oder unterbrechen. Zeige auf einen Träger oder tippe ihn an, um zu hören, was Fe über sie verraten kann","fe.zoneD.heading":"Das Resonanzlabor","fe.zoneD.kicker":"Zone D · Resonanzlabor","fe.zoneD.lede":"Ti verifiziert anhand seines Gitters und Fi anhand eines Grundtons. Fe verifiziert anhand des Feldes zwischen den Menschen, daher erzeugt dieses Labor seine Ereignisse im Raum und nicht in der Kammer. Drei machen es kohärenter, drei nehmen etwas weg – und eines davon kostet mehr als die anderen fünf zusammen.","fe.zoneD.legendHtml":"<strong>Lesen des Glyphs:</strong> Jede Person trägt eine Hand, die ihre Phase zeigt — wenn der Raum übereinstimmt, richten sich die Hände aus. Der Ring um den Kern sind die Farben des Raums nach Gewicht, und die Scheibe darin ist ihr Durchschnitt. Diese Scheibe ist die einzige Farbe, die Fe hat.","fe.zoneE.lede":"Muster aus der Praxis — wie Fe sich im Alltag zeigt."};export{e as _meta,n as default};
